/* Closed-form oracle for the owned Graphics I and II images (tests/roms/src/legacy_modes.asm and
   tests/roms/src/legacy_sprites.asm).

   The picture is a function of the generated scene, in the tile-index domain: a tile number from a
   column and a row, a pattern byte from a tile and a row, a colour byte from a tile group. Nothing
   here computes a video memory address; the image places the same generated bytes at the table
   addresses the registers select, and the renderer reads them back by address arithmetic. The
   scene formulas are written once in the header of legacy_modes.asm and repeated as code below.

   Modes (argv[4]):
     literals  checks every formula against hand-computed values and, with a csv path in argv[5],
               every legacy_sprites row of the csv against legacy_status(); exits 1 on a mismatch
     rows      prints "<id>:<name> <hex>" for every record legacy_sprites reports
     digest    prints the SHA-256 of the expected 256 by 192 field: one little-endian RGB444 word
               (0BBBBGGGGRRRR) per dot, the bytes cogmaster-run --hash hashes for this crop, so the
               two digests compare the same bytes
     compare   runs the image through the public API and compares every dot
   argv: image variant profile mode [frames, or the scenario number for sprites]. literals and
   rows ignore the first three. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "cogmaster.h"
#include "sha256.h"
#include "../check.h"

enum profile { PROFILE_SMS1, PROFILE_SMS2, PROFILE_GG, PROFILE_COUNT };
enum variant {
    VARIANT_G1,
    VARIANT_G2,
    VARIANT_G2_MASKED,
    VARIANT_G2_LATE,
    VARIANT_G2_LATE_BEFORE,
    VARIANT_G2_SWITCH,
    VARIANT_SPRITES,
    VARIANT_COUNT
};

static const char *const profile_names[PROFILE_COUNT] = {"sms1", "sms2", "gg"};
static const char *const variant_names[VARIANT_COUNT] = {
    "g1", "g2", "g2_masked", "g2_late", "g2_late_before", "g2_switch", "sprites"};

/* R7 low nibble: the backdrop colour the legacy_modes images program. */
#define BACKDROP_NIBBLE 11u
#define FIELD_W 256u
#define FIELD_H 192u

/* The Master System fixed palette as six-bit BBGGRR values (SMS Power palette page; the same
   sixteen values in ares ms/vdp/dac.cpp at 9408cb43d494, read for facts). A model: no source
   measures the Sega chip's legacy palette. */
static const uint8_t fixed_palette[16] = {0x00, 0x00, 0x08, 0x0C, 0x10, 0x30, 0x01, 0x3C,
                                          0x02, 0x03, 0x05, 0x0F, 0x04, 0x33, 0x15, 0x3F};

/* Six-bit BBGGRR to RGB444 words 0BBBBGGGGRRRR: each two-bit channel c becomes c * 5. */
static uint16_t rgb444(uint32_t six)
{
    uint32_t r = six & 3u, g = (six >> 2) & 3u, b = (six >> 4) & 3u;
    return (uint16_t)((b * 5u) << 8 | (g * 5u) << 4 | (r * 5u));
}

/* The colour RAM table the images write: entry i holds (13 i + 5) & 63. */
static uint32_t cram_value(uint32_t i)
{
    return (13u * i + 5u) & 63u;
}

/* Palette entry n. Master System 1 and 2: the fixed table. Game Gear in Master System video
   mode: colour RAM entry 16 + n (msvdp section 14; a model, ares uses the fixed table
   everywhere). The images write entries 16 to 31 with a table that differs from the fixed
   one, so the two oracles give different digests. */
static uint16_t palette(enum profile p, uint32_t n)
{
    n &= 15u;
    return p == PROFILE_GG ? rgb444(cram_value(16u + n)) : rgb444(fixed_palette[n]);
}

/* Graphics I (TI TMS9918A manual 2.4.1), by tile: the name of a cell, the pattern byte of a
   tile row, the colour byte of a group of eight tiles. A set pattern bit shows the high
   nibble, a clear bit the low nibble, and nibble 0 shows the backdrop. */
static uint32_t scene_name(uint32_t col, uint32_t row)
{
    return (32u * row + col) & 255u;
}
static uint32_t g1_pattern(uint32_t tile, uint32_t r)
{
    return (7u * tile + 29u * r) & 255u;
}
static uint32_t g1_colour(uint32_t group)
{
    return ((5u * group + 1u) & 15u) << 4 | ((3u * group) & 15u);
}

static uint16_t nibble_colour(enum profile p, uint32_t bits, uint32_t colour, uint32_t x)
{
    uint32_t nibble = (bits >> (7u - (x & 7u))) & 1u ? colour >> 4 : colour & 15u;
    return palette(p, nibble == 0u ? BACKDROP_NIBBLE : nibble);
}

static uint16_t pixel_g1(enum profile p, uint32_t x, uint32_t y)
{
    uint32_t tile = scene_name(x >> 3, y >> 3);
    return nibble_colour(p, g1_pattern(tile, y & 7u), g1_colour(tile >> 3), x);
}

/* Graphics II (TI manual table 3-2), by index: idx is the name with the third of the screen
   (row / 8) above it, 0 to 767, and each index owns eight pattern bytes and eight colour bytes,
   one per row. Pattern and colour are generated per (idx, row); a byte of the colour table holds
   the high nibble for a set bit and the low nibble for a clear bit.
     pattern(idx, r)  = (7 t + 101 th + 29 r) & 255
     colour hi(idx,r) = (5 t + 3 th + 3 r + 1) & 15
     colour lo(idx,r) = (3 t + 5 th + 7 r) & 15            with t = idx & 255, th = idx >> 8
   Model, not a measurement: the Master System 1 ANDs the index with the low bits of R4 (pattern)
   and R3 (colour) that the TI manual says must be set to all ones (Sean Young's TMS9918A notes
   describe the AND), so the index becomes idx & (((R4 & 3) << 8) | 255) for the pattern and
   idx & (((R3 & 127) << 3) | 7) for the colour. Master System 2 and Game Gear in Master System
   mode do not mask (msvdp, a model with about 60 percent confidence). */
static uint32_t g2_pattern(uint32_t idx, uint32_t r)
{
    return (7u * (idx & 255u) + 101u * (idx >> 8) + 29u * r) & 255u;
}
static uint32_t g2_colour(uint32_t idx, uint32_t r)
{
    uint32_t t = idx & 255u, th = idx >> 8;
    return ((5u * t + 3u * th + 3u * r + 1u) & 15u) << 4 | ((3u * t + 5u * th + 7u * r) & 15u);
}

static uint16_t pixel_g2(enum profile p, uint32_t r3, uint32_t r4, uint32_t x, uint32_t y)
{
    uint32_t row = y >> 3;
    uint32_t idx = (row >> 3) << 8 | scene_name(x >> 3, row);
    uint32_t pidx = idx, cidx = idx;
    if (p == PROFILE_SMS1) {
        pidx &= ((r4 & 3u) << 8) | 255u;
        cidx &= ((r3 & 127u) << 3) | 7u;
    }
    return nibble_colour(p, g2_pattern(pidx, y & 7u), g2_colour(cidx, y & 7u), x);
}

/* Mode 4 with the zero tile everywhere shows colour RAM entry 0 on every dot. */
static uint16_t pixel_mode4(void)
{
    return rgb444(cram_value(0u));
}

/* The switch image enables the line interrupt on line SWITCH_IRQ_LINE (R10, which fires on the
   line of that number at tick 608). The handler runs in the next line and writes R0 about 200
   ticks into it (the interrupt is accepted within 12 ticks, the handler spends about 270 ticks on
   a push, a status read and a control port pair; video.md timing model), so the lines before
   SWITCH_LINE are mode 4, the lines after it Graphics II and the line itself a mix that only a
   hash pins. */
#define SWITCH_IRQ_LINE 47u
#define SWITCH_LINE (SWITCH_IRQ_LINE + 1u)

/* The sprite scenarios of legacy_sprites. The image clears and loads video memory with the display
   off (the first eight frames), then shows one scenario for two frames and reads the status once at
   the end of the first. SPRITES_FIRST_FRAME is the number of frames after which the first
   scenario's picture is the completed one, measured from the image's schedule: a host frame ends at
   the frame event, so vertical blank, where the image writes each scenario, is the start of a host
   frame and the picture completed after frame 9 is the first with scenario 1 in it. Each scenario
   programs its own R7, so a compare one frame off meets another scenario's backdrop and fails. */
#define SCENARIO_FRAMES 2u
#define SPRITES_FIRST_FRAME 9u

struct sprite {
    uint8_t y, x, name, attr;
};
struct scenario {
    const char *name;
    uint8_t backdrop; /* R7 low nibble */
    uint8_t r0;    /* R0: bit 3 is set in one scenario and ignored; bit 4 is the line interrupt */
    uint8_t r1;    /* R1 bit 1: 16 by 16, bit 0: magnified */
    uint8_t count; /* entries listed; the rest of the 32 read Y $D0 */
    struct sprite list[10];
};

/* One line of the SAT per sprite: Y, X, name, attribute (bit 7 early clock, bits 3..0 colour). The
   generated patterns: name 0 blank, 1 solid, 2 the left column, 3 the right column, and
   (53 n + 17 r + 1) & 255 for any other name n at row r. A 16 by 16 sprite takes the name with
   its two low bits cleared and the four names that follow: top left, bottom left, top right,
   bottom right. */
static const struct scenario scenarios[] = {
    {"single_8x8", 2, 0, 0, 1, {{39, 100, 1, 5}}},
    {"size_16x16", 3, 0, 2, 1, {{39, 100, 8, 7}}},
    {"magnified_8x8", 4, 0, 1, 1, {{39, 100, 9, 9}}},
    {"magnified_16x16", 5, 0, 3, 1, {{39, 100, 8, 11}}},
    {"early_clock", 6, 8, 0, 3, {{15, 70, 1, 0x82}, {47, 70, 3, 2}, {79, 36, 1, 0x84}}},
    {"end_of_list", 7, 0, 0, 3, {{19, 40, 1, 5}, {0xD0, 0, 0, 0}, {19, 120, 1, 6}}},
    {"y_ff", 8, 0, 0, 1, {{0xFF, 60, 12, 4}}},
    {"y_e8_magnified_16x16", 9, 0, 3, 1, {{0xE8, 60, 8, 5}}},
    {"y_e0_magnified_16x16", 10, 0, 3, 1, {{0xE0, 60, 8, 6}}},
    {"five_on_a_line",
     11,
     0,
     0,
     5,
     {{39, 20, 1, 2}, {39, 40, 1, 3}, {39, 60, 1, 4}, {39, 80, 1, 5}, {39, 100, 1, 6}}},
    {"overflow_two_lines",
     12,
     0,
     0,
     10,
     {{99, 20, 1, 2},
      {99, 40, 1, 3},
      {99, 60, 1, 4},
      {99, 80, 1, 5},
      {99, 100, 1, 6},
      {39, 20, 1, 7},
      {39, 40, 1, 8},
      {39, 60, 1, 9},
      {39, 80, 1, 10},
      {39, 100, 1, 11}}},
    {"overlap_opaque", 13, 0, 0, 2, {{59, 100, 1, 5}, {59, 104, 1, 6}}},
    {"overlap_colour0", 14, 0, 0, 2, {{59, 100, 1, 0}, {59, 104, 1, 0}}},
    {"touching", 2, 0, 0, 2, {{59, 100, 1, 5}, {59, 108, 1, 6}}},
    {"overlap_off_left_edge", 3, 0, 0, 3, {{59, 10, 1, 0x85}, {59, 14, 1, 0x86}, {99, 100, 1, 7}}},
    {"after_terminator",
     4,
     0,
     0,
     4,
     {{19, 40, 1, 3}, {0xD0, 0, 0, 0}, {59, 100, 1, 5}, {59, 104, 1, 6}}},
    {"fifth_overlaps",
     5,
     0,
     0,
     5,
     {{59, 20, 1, 2}, {59, 40, 1, 3}, {59, 60, 1, 4}, {59, 80, 1, 5}, {59, 84, 1, 6}}},
    {"four_on_a_line",
     6,
     0,
     0,
     4,
     {{59, 20, 1, 2}, {59, 50, 1, 3}, {59, 80, 1, 4}, {59, 110, 1, 5}}},
    {"magnified_overlap", 7, 0, 1, 2, {{59, 100, 1, 5}, {59, 108, 1, 6}}},
    /* The tail scenario: four sprites start on line TAIL_LINE + 1 and a fifth ends on it, so the
       fifth Y match is on exactly that line. R0 bit 4 enables the line interrupt. */
    {"tail",
     8,
     0x10,
     0,
     5,
     {{80, 20, 1, 2}, {80, 50, 1, 3}, {80, 80, 1, 4}, {80, 110, 1, 5}, {73, 140, 1, 6}}},
};
#define SCENARIO_COUNT (sizeof scenarios / sizeof scenarios[0])
#define TAIL_SCENARIO (SCENARIO_COUNT - 1u)

/* The generated sprite patterns. */
static uint32_t sprite_pattern(uint32_t name, uint32_t r)
{
    switch (name) {
    case 0u:
        return 0u;
    case 1u:
        return 255u;
    case 2u:
        return 128u;
    case 3u:
        return 1u;
    default:
        return (53u * name + 17u * r + 1u) & 255u;
    }
}

/* The sprites in force: those before the first Y $D0 (TI TMS9918A manual 2.4.5; every source
   agrees that $D0 ends the list in the legacy modes). */
static uint32_t live_count(const struct scenario *sc)
{
    uint32_t n = 0u;
    while (n < sc->count && sc->list[n].y != 0xD0u)
        n++;
    return n;
}
static int sprite_span(const struct scenario *sc)
{
    return (sc->r1 & 2u ? 16 : 8) * (sc->r1 & 1u ? 2 : 1);
}

/* Y >= $E0 is negative, the top line is Y - 255 and otherwise Y + 1 (model: ares and the TI
   manual's range read that way, MAME's TMS file uses > $E0, MAME's SMS path >= $F0; the rows
   y_e0 and y_e8 pin the choice). */
static int sprite_top(const struct sprite *s)
{
    return s->y >= 0xE0u ? (int)s->y - 255 : (int)s->y + 1;
}
/* The early clock bit, attribute bit 7, moves the sprite 32 dots left; R0 bit 3 does nothing in
   the legacy modes (model, MAME and ares agree, msvdp says it shifts by 8). */
static int sprite_left(const struct sprite *s)
{
    return (int)s->x - ((s->attr & 0x80u) != 0u ? 32 : 0);
}

/* Whether the pattern of sprite s has a set bit at screen dot x of the line. */
static int sprite_bit(const struct scenario *sc, const struct sprite *s, int line, int x)
{
    int span = sprite_span(sc), dx = x - sprite_left(s), dy = line - sprite_top(s);
    if (dx < 0 || dy < 0 || dx >= span || dy >= span)
        return 0;
    uint32_t mag = (sc->r1 & 1u) != 0u ? 2u : 1u;
    uint32_t sx = (uint32_t)dx / mag, sy = (uint32_t)dy / mag, name = s->name;
    if ((sc->r1 & 2u) != 0u)
        name = (name & 0xFCu) + (sx >> 3) * 2u + (sy >> 3);
    return (int)((sprite_pattern(name, sy & 7u) >> (7u - (sx & 7u))) & 1u);
}

/* One line's sprite list: a walk of the SAT in index order, never the slot structure. The first
   four Y matches are shown (lower index wins); the fifth match, if any, is the fifth sprite. A
   match is a Y match alone: a transparent or off-screen sprite counts (a model). */
struct line_scan {
    uint32_t shown[4];
    uint32_t count;
    int fifth; /* SAT index of the fifth match, or -1 */
};
static void scan_line(const struct scenario *sc, int line, struct line_scan *out)
{
    uint32_t matches = 0u;
    out->count = 0u;
    out->fifth = -1;
    for (uint32_t i = 0u; i < live_count(sc); i++) {
        int top = sprite_top(&sc->list[i]);
        if (line < top || line >= top + sprite_span(sc))
            continue;
        matches++;
        if (matches <= 4u)
            out->shown[out->count++] = i;
        else if (matches == 5u)
            out->fifth = (int)i;
    }
}

static uint16_t pixel_sprites(enum profile p, const struct scenario *sc, uint32_t x, uint32_t y)
{
    struct line_scan scan;
    scan_line(sc, (int)y, &scan);
    for (uint32_t k = 0u; k < scan.count; k++) {
        const struct sprite *s = &sc->list[scan.shown[k]];
        if ((s->attr & 15u) != 0u && sprite_bit(sc, s, (int)y, (int)x))
            return palette(p, s->attr & 15u);
    }
    return palette(p, sc->backdrop);
}

/* The status byte a read returns after the dots of line read_line have been drawn; a line of
   FIELD_H or more is a read in vertical blank, after the frame flag. Bit 7 the frame flag. Bit 6
   the fifth sprite flag: some line before the read had a fifth Y match. Bits 4..0 the SAT index of
   the fifth match on the first such line, first wins until a read (a model); $1F when bit 6
   is clear. Bit 5 coincidence: on some line two of its first four matches both have a set pattern
   bit on one dot x in 0..255, colour 0 included (the datasheet counts the pattern bits; a model).
   Every status row of the legacy_sprites mailbox cites this function. */
static uint32_t legacy_status(const struct scenario *sc, uint32_t read_line)
{
    uint32_t last = read_line >= FIELD_H ? FIELD_H - 1u : read_line;
    uint32_t coincidence = 0u;
    int fifth = -1;
    for (uint32_t line = 0u; line <= last; line++) {
        struct line_scan scan;
        scan_line(sc, (int)line, &scan);
        if (fifth < 0 && scan.fifth >= 0)
            fifth = scan.fifth;
        for (int x = 0; x < (int)FIELD_W && coincidence == 0u; x++) {
            uint32_t set = 0u;
            for (uint32_t k = 0u; k < scan.count; k++)
                set += (uint32_t)sprite_bit(sc, &sc->list[scan.shown[k]], (int)line, x);
            coincidence = set >= 2u;
        }
    }
    return (read_line >= FIELD_H ? 0x80u : 0u) | (coincidence != 0u ? 0x20u : 0u) |
           (fifth >= 0 ? 0x40u | (uint32_t)fifth : 0x1Fu);
}

/* The tail read. Line TAIL_LINE has no fifth match but TAIL_LINE + 1 has: the scan for that line
   runs at tick 600 of TAIL_LINE and the flag asserts at dot 0 of the next line, tick 684. The
   image reads the status once in between, from a line interrupt on TAIL_LINE - 1, and the H
   counter 45 ticks later (an IN of 33 ticks whose access is at tick 30, an LD of 12, the next IN
   accessed at tick 30). H counter values follow the table of video.md, in active ticks:
   0 to 559 read $08 to $93, 560 to 651 read $E9 to $FF, 652 to 683 read $00 to $07, four ticks to
   a value. A status read at ticks 600 to 606 is followed by an H read at 645 to 651, $FE or $FF,
   which wraps below the others, so the range starts at the first read whose H is $00 (tick 652,
   a status read at tick 607) and ends at the H of the last status tick plus 45, tick 728, which
   is tick 44 of the next line. A value in the range proves the status read was in ticks 607 to
   683 of TAIL_LINE. */
#define TAIL_LINE 80u
#define LINE_TICKS 684u
#define TAIL_PAIR_TICKS 45u
static uint32_t h_counter(uint32_t tick)
{
    tick %= LINE_TICKS;
    if (tick < 560u)
        return 0x08u + tick / 4u;
    return tick < 652u ? 0xE9u + (tick - 560u) / 4u : (tick - 652u) / 4u;
}
#define TAIL_HCOUNT_LO h_counter(652u)
#define TAIL_HCOUNT_HI h_counter(LINE_TICKS - 1u + TAIL_PAIR_TICKS)

/* The mailbox records of legacy_sprites: id, name and the text of the csv's expected column. */
struct record {
    uint32_t id;
    char name[40];
    char expected[16];
};
static size_t build_records(struct record *out)
{
    size_t n = 0u;
    for (size_t i = 0u; i < SCENARIO_COUNT; i++) {
        const struct scenario *sc = &scenarios[i];
        if (i == TAIL_SCENARIO) {
            out[n].id = (uint32_t)i + 1u;
            snprintf(out[n].name, sizeof out[n].name, "tail_status");
            snprintf(out[n++].expected, sizeof out[n].expected, "%04X",
                     legacy_status(sc, TAIL_LINE));
            out[n].id = (uint32_t)i + 2u;
            snprintf(out[n].name, sizeof out[n].name, "tail_hcount");
            snprintf(out[n++].expected, sizeof out[n].expected, "%04X-%04X", TAIL_HCOUNT_LO,
                     TAIL_HCOUNT_HI);
            out[n].id = (uint32_t)i + 3u;
            snprintf(out[n].name, sizeof out[n].name, "tail_frame_status");
        } else {
            out[n].id = (uint32_t)i + 1u;
            snprintf(out[n].name, sizeof out[n].name, "%s", sc->name);
        }
        snprintf(out[n++].expected, sizeof out[n].expected, "%04X", legacy_status(sc, FIELD_H));
    }
    return n;
}

static uint16_t pixel(enum variant v, enum profile p, uint32_t scenario, uint32_t x, uint32_t y)
{
    switch (v) {
    case VARIANT_G1:
        return pixel_g1(p, x, y);
    case VARIANT_G2:
        return pixel_g2(p, 255u, 3u, x, y);
    case VARIANT_G2_MASKED:
        return pixel_g2(p, 0x9Fu, 0u, x, y);
    case VARIANT_G2_LATE:
        return pixel_g2(p, 0x7Fu, 7u, x, y);
    case VARIANT_G2_LATE_BEFORE:
        return pixel_mode4();
    case VARIANT_G2_SWITCH:
        return y < SWITCH_LINE ? pixel_mode4() : pixel_g2(p, 0x7Fu, 7u, x, y);
    default:
        return pixel_sprites(p, &scenarios[scenario], x, y);
    }
}

/* Hand-computed pixels. Each group shows the tile, the row, the pattern byte, the colour byte and
   the nibble that were worked out by hand from the formulas above.
   Palette: fixed entry 1 is 000, 2 is 0A0, 3 is 0F0, 5 is F00, 6 is 005, 7 is FF0, 8 is 00A, 9 is
   00F, 11 is 0FF, 12 is 050, 13 is F0F, 14 is 555. Colour RAM 16 + n is (13 (16 + n) + 5) & 63, so
   n = 11 gives 36 = 100100 (blue 2, green 1, red 0) = A50, n = 1 gives 34 = A0A, n = 3 gives
   60 = FF0, n = 5 gives 22 = 55A, n = 6 gives 35 = A0F, n = 7 gives 48 = F00, n = 9 gives 10 = 0AA,
   n = 12 gives 49 = F05, n = 13 gives 62 = FFA. Colour RAM entry 0 is 5 = 000101 = 055. */
struct literal {
    enum variant variant;
    enum profile profile;
    uint32_t scenario, x, y;
    uint16_t want;
};
static const struct literal literals[] = {
    /* Graphics I (0, 0): tile 0, row 0, pattern 0, colour byte 10 (high nibble 1, low 0): bit
       clear, low nibble 0, so the backdrop, R7 low nibble 11. */
    {VARIANT_G1, PROFILE_SMS2, 0u, 0u, 0u, 0x0FF},
    {VARIANT_G1, PROFILE_SMS1, 0u, 0u, 0u, 0x0FF},
    {VARIANT_G1, PROFILE_GG, 0u, 0u, 0u, 0xA50},
    /* (13, 0): tile 1, row 0, pattern 07. The dot is bit 7 - (13 mod 8) = 2 of the pattern:
       set, so the high nibble 1 of colour byte 10, which is entry 1 of the palette. */
    {VARIANT_G1, PROFILE_SMS2, 0u, 13u, 0u, 0x000},
    {VARIANT_G1, PROFILE_GG, 0u, 13u, 0u, 0xA0A},
    /* Tile 8 (column 8), row 0: pattern 38, colour byte 63 (group 1). x 66 is bit 5: set, high
       nibble 6; x 64 is bit 7: clear, low nibble 3. */
    {VARIANT_G1, PROFILE_SMS2, 0u, 66u, 0u, 0x005},
    {VARIANT_G1, PROFILE_GG, 0u, 66u, 0u, 0xA0F},
    {VARIANT_G1, PROFILE_SMS2, 0u, 64u, 0u, 0x0F0},
    {VARIANT_G1, PROFILE_GG, 0u, 64u, 0u, 0xFF0},
    /* Tile 24, row 0: pattern A8, colour byte 09 (group 3, a zero high nibble). x 192 is bit 7:
       set, high nibble 0, so the backdrop. x 193 is bit 6: clear, low nibble 9. */
    {VARIANT_G1, PROFILE_SMS2, 0u, 192u, 0u, 0x0FF},
    {VARIANT_G1, PROFILE_SMS2, 0u, 193u, 0u, 0x00F},
    {VARIANT_G1, PROFILE_GG, 0u, 193u, 0u, 0x0AA},
    /* Row 1, column 0 is tile 32: pattern E0, colour byte 5C (group 4). (0, 8) is bit 7: set,
       high nibble 5. (3, 8) is bit 4: clear, low nibble 12. */
    {VARIANT_G1, PROFILE_SMS2, 0u, 0u, 8u, 0xF00},
    {VARIANT_G1, PROFILE_SMS2, 0u, 3u, 8u, 0x050},
    {VARIANT_G1, PROFILE_GG, 0u, 3u, 8u, 0xF05},
    /* Row 9 wraps the name: 32 * 9 + 3 = 291, and 291 & 255 = 35: pattern F5 for row 0,
       colour byte 5C. (24, 72) is bit 7: set, high nibble 5. */
    {VARIANT_G1, PROFILE_SMS2, 0u, 24u, 72u, 0xF00},
    /* The last dot: column 31, row 23, tile 767 & 255 = 255, row 7: pattern (7 * 255 + 29 * 7)
       & 255 = C4, bit 0: clear. Colour byte for group 31: (156 & 15) = 12 high, 93 & 15 = 13 low:
       CD, so low nibble 13. */
    {VARIANT_G1, PROFILE_SMS2, 0u, 255u, 191u, 0xF0F},
    {VARIANT_G1, PROFILE_GG, 0u, 255u, 191u, 0xFFA},

    /* Graphics II (R3 FF, R4 03, no mask effect). (0, 0): idx 0, pattern 0, colour byte 10:
       clear, low nibble 0, backdrop. */
    {VARIANT_G2, PROFILE_SMS2, 0u, 0u, 0u, 0x0FF},
    {VARIANT_G2, PROFILE_GG, 0u, 0u, 0u, 0xA50},
    /* Line 63 is row 7, the last row of the first third: name 224, idx 224, row 7: pattern
       (7 * 224 + 29 * 7) & 255 = EB, bit 7 set; colour high nibble (5 * 224 + 3 * 7 + 1) & 15 =
       1142 & 15 = 6, so entry 6. Line 64 is row 8, the first row of the second third: name 0,
       idx 256, row 0: pattern 101 = 65, bit 7 clear; colour low nibble (5 * 1) & 15 = 5, so
       entry 5. */
    {VARIANT_G2, PROFILE_SMS2, 0u, 0u, 63u, 0x005},
    {VARIANT_G2, PROFILE_SMS2, 0u, 0u, 64u, 0xF00},
    {VARIANT_G2, PROFILE_GG, 0u, 0u, 63u, 0xA0F},
    {VARIANT_G2, PROFILE_GG, 0u, 0u, 64u, 0x55A},
    /* The all-ones masks change nothing on the Master System 1. */
    {VARIANT_G2, PROFILE_SMS1, 0u, 0u, 64u, 0xF00},
    /* Line 127 is row 15 (idx 256 + 224 = 480, row 7): pattern (7 * 224 + 101 + 203) & 255 = 50,
       bit 7 clear, colour low nibble (3 * 224 + 5 + 49) & 15 = 6, so entry 6. Line 128 is row 16
       (idx 512, row 0): pattern 202 = CA, bit 7 set, colour high nibble (3 * 2 + 1) & 15 = 7. */
    {VARIANT_G2, PROFILE_SMS2, 0u, 0u, 127u, 0x005},
    {VARIANT_G2, PROFILE_SMS2, 0u, 0u, 128u, 0xFF0},
    {VARIANT_G2, PROFILE_GG, 0u, 0u, 128u, 0xF00},

    /* R3 9F, R4 00: both masks bite on the Master System 1. At (0, 64) idx 256 becomes 0 for the
       pattern and for the colour, so the dot is the backdrop on the Master System 1 and the
       third-two data on the others. (0, 128) idx 512 also becomes 0. The last dot, idx 767,
       becomes 255 on the Master System 1: pattern C4, bit 0 clear, colour low nibble
       (3 * 255 + 49) & 15 = 14, entry 14 = 555; unmasked it is pattern 8E, low nibble 8. */
    {VARIANT_G2_MASKED, PROFILE_SMS1, 0u, 0u, 64u, 0x0FF},
    {VARIANT_G2_MASKED, PROFILE_SMS2, 0u, 0u, 64u, 0xF00},
    {VARIANT_G2_MASKED, PROFILE_GG, 0u, 0u, 64u, 0x55A},
    {VARIANT_G2_MASKED, PROFILE_SMS1, 0u, 0u, 128u, 0x0FF},
    {VARIANT_G2_MASKED, PROFILE_SMS1, 0u, 255u, 191u, 0x555},
    {VARIANT_G2_MASKED, PROFILE_SMS2, 0u, 255u, 191u, 0x00A},

    /* Entered after frame 600: Graphics II with R3 7F, R4 07, which mask nothing. Before the
       switch the screen is mode 4 with the zero tile: colour RAM entry 0 = 055. */
    {VARIANT_G2_LATE, PROFILE_SMS1, 0u, 0u, 64u, 0xF00},
    {VARIANT_G2_LATE, PROFILE_SMS2, 0u, 0u, 128u, 0xFF0},
    {VARIANT_G2_LATE_BEFORE, PROFILE_SMS1, 0u, 0u, 0u, 0x055},
    {VARIANT_G2_LATE_BEFORE, PROFILE_GG, 0u, 255u, 191u, 0x055},

    /* The switch image. Lines before 48 are mode 4: 055. Line 49 is row 6 (name 192), row 1:
       pattern (7 * 192 + 29) & 255 = 5D, bit 7 clear, colour low nibble
       (3 * 192 + 7) & 15 = 7, entry 7 = FF0. */
    {VARIANT_G2_SWITCH, PROFILE_SMS2, 0u, 0u, 0u, 0x055},
    {VARIANT_G2_SWITCH, PROFILE_GG, 0u, 255u, 47u, 0x055},
    {VARIANT_G2_SWITCH, PROFILE_SMS2, 0u, 0u, 49u, 0xFF0},
    {VARIANT_G2_SWITCH, PROFILE_SMS1, 0u, 0u, 64u, 0xF00},

    /* Sprites, by scenario index. single_8x8 is a solid 8 by 8 sprite, colour 5, at Y 39 X 100, so
       lines 40 to 47 and dots 100 to 107; the backdrop is entry 2 = 0A0. */
    {VARIANT_SPRITES, PROFILE_SMS2, 0u, 100u, 40u, 0xF00},
    {VARIANT_SPRITES, PROFILE_SMS2, 0u, 107u, 47u, 0xF00},
    {VARIANT_SPRITES, PROFILE_SMS2, 0u, 99u, 40u, 0x0A0},
    {VARIANT_SPRITES, PROFILE_SMS2, 0u, 108u, 47u, 0x0A0},
    {VARIANT_SPRITES, PROFILE_SMS2, 0u, 100u, 39u, 0x0A0},
    {VARIANT_SPRITES, PROFILE_SMS2, 0u, 100u, 48u, 0x0A0},
    /* size_16x16: name 8 at Y 39 X 100, colour 7, backdrop entry 3 = 0F0. The top left quadrant
       is name 8: the pattern byte for row 0 is (53 * 8 + 1) & 255 = A9, bit 7 set at dot 100 and
       bit 6 clear at dot 101. The bottom left is name 9, row 0: (53 * 9 + 1) & 255 = DE, bit 7 set
       at (100, 48). The top right is name 10 at dot 108, row 0: 13, bit 7 clear. */
    {VARIANT_SPRITES, PROFILE_SMS2, 1u, 100u, 40u, 0xFF0},
    {VARIANT_SPRITES, PROFILE_SMS2, 1u, 101u, 40u, 0x0F0},
    {VARIANT_SPRITES, PROFILE_SMS2, 1u, 100u, 48u, 0xFF0},
    {VARIANT_SPRITES, PROFILE_SMS2, 1u, 108u, 40u, 0x0F0},
    /* end_of_list: the sprite before the end of the list (Y 19, X 40, solid, colour 5) shows and
       the one after it (X 120, colour 6) does not; backdrop entry 7 = FF0. */
    {VARIANT_SPRITES, PROFILE_SMS2, 5u, 40u, 20u, 0xF00},
    {VARIANT_SPRITES, PROFILE_SMS2, 5u, 120u, 20u, 0xFF0},
    /* y_ff: Y $FF, name 12, colour 4, backdrop entry 8 = 00A. The top line is line 0 and shows
       pattern row 0: (53 * 12 + 1) & 255 = 7D = 01111101, bit 7 clear at dot 60, bit 6 set at
       dot 61 (colour 4 is 500). */
    {VARIANT_SPRITES, PROFILE_SMS2, 6u, 60u, 0u, 0x00A},
    {VARIANT_SPRITES, PROFILE_SMS2, 6u, 61u, 0u, 0x500},
    /* y_e8: Y $E8, 16 by 16 magnified, top line 232 - 255 = -23, so line 0 shows source row
       (23 / 2) = 11, name 9 row 3: (53 * 9 + 17 * 3 + 1) & 255 = 11 = 00010001; dot 66 is source
       column 3, bit 4, set: colour 5 = F00. Line 8 is source row 15, row 7 of name 9:
       (477 + 119 + 1) & 255 = 55 = 01010101, dot 60 clear, dot 62 (column 1) set: colour 5.
       Line 9 is past the sprite: the backdrop, entry 9 = 00F. */
    {VARIANT_SPRITES, PROFILE_SMS2, 7u, 66u, 0u, 0xF00},
    {VARIANT_SPRITES, PROFILE_SMS2, 7u, 62u, 8u, 0xF00},
    {VARIANT_SPRITES, PROFILE_SMS2, 7u, 60u, 8u, 0x00F},
    {VARIANT_SPRITES, PROFILE_SMS2, 7u, 61u, 9u, 0x00F},
    /* y_e0: Y $E0, top line 224 - 255 = -31, so only line 0 shows, source row 15: name 9 row 7,
       55 = 01010101, dot 62 (column 1) set, colour 6 = 005. Line 1 is the backdrop, entry 10 =
       055. */
    {VARIANT_SPRITES, PROFILE_SMS2, 8u, 62u, 0u, 0x005},
    {VARIANT_SPRITES, PROFILE_SMS2, 8u, 62u, 1u, 0x055},
    /* five_on_a_line: five solid sprites on line 40, X 20 to 100 and colours 2 to 6. The fourth
       (X 80, colour 5) is drawn and the fifth (X 100) is not; backdrop entry 11 = 0FF. */
    {VARIANT_SPRITES, PROFILE_SMS2, 9u, 80u, 40u, 0xF00},
    {VARIANT_SPRITES, PROFILE_SMS2, 9u, 100u, 40u, 0x0FF},
};

/* Status bytes worked out by hand from the scenario lists (the csv is not hand typed; these check
   legacy_status itself). The frame flag is bit 7. A lone sprite (single_8x8) sets nothing else: 9F.
   five_on_a_line: the fifth, SAT index 4, sets bit 6: C4. overflow_two_lines: the first line in
   raster order is line 40, whose fifth match is entry 9, and line 100's fifth match, entry 4, does
   not replace it: C9. overlap_opaque: two solid sprites overlap and set bit 5: BF.
   overlap_colour0: colour 0 sprites still collide: BF. touching: no overlap: 9F.
   overlap_off_left_edge: the overlap is at negative dots only: 9F. after_terminator: sprites past
   the end of list do not collide: 9F. fifth_overlaps: the fifth sprite is not drawn, so no
   bit 5: C4. magnified_overlap: doubled, the touching pair overlaps: BF. tail: the read at line 80
   has no flag yet, 1F, and the frame-end read has bit 6 with entry 4: C4. */
struct status_literal {
    uint32_t scenario, read_line;
    uint32_t want;
};
static const struct status_literal status_literals[] = {
    {0u, FIELD_H, 0x9Fu},  {9u, FIELD_H, 0xC4u},  {10u, FIELD_H, 0xC9u},   {11u, FIELD_H, 0xBFu},
    {12u, FIELD_H, 0xBFu}, {13u, FIELD_H, 0x9Fu}, {14u, FIELD_H, 0x9Fu},   {15u, FIELD_H, 0x9Fu},
    {16u, FIELD_H, 0xC4u}, {18u, FIELD_H, 0xBFu}, {19u, TAIL_LINE, 0x1Fu}, {19u, FIELD_H, 0xC4u},
};

static void digest_of(enum variant v, enum profile p, uint32_t scenario, char *hex)
{
    cogmaster__sha256 hash;
    cogmaster__sha256_init(&hash);
    for (uint32_t y = 0u; y < FIELD_H; y++) {
        for (uint32_t x = 0u; x < FIELD_W; x++) {
            uint16_t want = pixel(v, p, scenario, x, y);
            uint8_t bytes[2] = {(uint8_t)want, (uint8_t)(want >> 8)};
            cogmaster__sha256_update(&hash, bytes, sizeof bytes);
        }
    }
    uint8_t digest[32];
    cogmaster__sha256_final(&hash, digest);
    for (uint32_t i = 0u; i < 32u; i++)
        snprintf(hex + 2u * i, 3u, "%02x", digest[i]);
}

/* Every legacy_sprites row of the csv equals what legacy_status computes, every record has a row
   and no row is left over, so no status expectation is a hand-typed value. */
static void check_csv(const char *path)
{
    struct record records[48];
    size_t count = build_records(records);
    uint32_t seen[48] = {0};
    FILE *file = fopen(path, "r");
    if (file == NULL) {
        fprintf(stderr, "cannot read %s\n", path);
        check_failures++;
        return;
    }
    char line[512];
    while (fgets(line, sizeof line, file) != NULL) {
        if (strncmp(line, "legacy_sprites,", 15) != 0)
            continue;
        /* rom,test,profile,expected,source,citation: the citation holds no comma. */
        char *field[6];
        size_t fields = 0u;
        for (char *s = line; fields < 6u;) {
            field[fields++] = s;
            char *comma = strchr(s, ',');
            if (comma == NULL)
                break;
            *comma = '\0';
            s = comma + 1;
        }
        if (fields != 6u) {
            fprintf(stderr, "csv row without six fields: %s\n", line);
            check_failures++;
            continue;
        }
        const char *test = field[1], *profile = field[2], *expected = field[3];
        const char *source = field[4], *citation = field[5];
        unsigned id = 0u;
        size_t found = count;
        if (sscanf(test, "%2x:", &id) == 1)
            for (size_t i = 0u; i < count; i++)
                if (records[i].id == id)
                    found = i;
        if (found == count) {
            fprintf(stderr, "csv row %s has no record\n", test);
            check_failures++;
            continue;
        }
        seen[found]++;
        const struct record *r = &records[found];
        int hcount = strcmp(r->name, "tail_hcount") == 0;
        CHECK(strchr(test, ':') != NULL &&
              strncmp(strchr(test, ':') + 1, r->name, strlen(r->name)) == 0);
        CHECK(strcmp(profile, "*") == 0);
        CHECK(strcmp(source, "derived") == 0);
        CHECK(strstr(citation, hcount ? "TAIL_HCOUNT" : "legacy_status") != NULL);
        if (strcmp(expected, r->expected) != 0) {
            fprintf(stderr, "csv row %s expects %s, the oracle computes %s\n", test, expected,
                    r->expected);
            check_failures++;
        }
    }
    CHECK(fclose(file) == 0);
    for (size_t i = 0u; i < count; i++) {
        if (seen[i] != 1u) {
            fprintf(stderr, "record %02X:%s has %u csv rows\n", records[i].id, records[i].name,
                    seen[i]);
            check_failures++;
        }
    }
}

static int check_literals(const char *csv)
{
    for (size_t i = 0u; i < sizeof literals / sizeof literals[0]; i++) {
        const struct literal *l = &literals[i];
        uint16_t got = pixel(l->variant, l->profile, l->scenario, l->x, l->y);
        if (got != l->want) {
            fprintf(stderr, "literal %zu: %s %s (%u,%u) is %03x, expected %03x\n", i,
                    variant_names[l->variant], profile_names[l->profile], l->x, l->y, got, l->want);
            check_failures++;
        }
    }
    for (size_t i = 0u; i < sizeof status_literals / sizeof status_literals[0]; i++) {
        const struct status_literal *l = &status_literals[i];
        uint32_t got = legacy_status(&scenarios[l->scenario], l->read_line);
        if (got != l->want) {
            fprintf(stderr, "status literal %zu: scenario %u line %u is %02X, expected %02X\n", i,
                    l->scenario, l->read_line, got, l->want);
            check_failures++;
        }
    }
    /* The tail range follows from the table in the comment above. */
    CHECK_EQ_HEX(TAIL_HCOUNT_LO, 0x00u);
    CHECK_EQ_HEX(TAIL_HCOUNT_HI, 0x13u);
    CHECK_EQ_HEX(h_counter(600u), 0xF3u);
    CHECK_EQ_HEX(h_counter(607u), 0xF4u);
    CHECK_EQ_HEX(h_counter(608u), 0xF5u);
    CHECK_EQ_HEX(h_counter(0u), 0x08u);
    /* The controls that make the digests mean something: the Game Gear palette differs from the
       fixed one, the Master System 1 masks bite in g2_masked, and they do not in g2. */
    char a[65], b[65];
    digest_of(VARIANT_G1, PROFILE_SMS2, 0u, a);
    digest_of(VARIANT_G1, PROFILE_GG, 0u, b);
    CHECK(strcmp(a, b) != 0);
    digest_of(VARIANT_G2_MASKED, PROFILE_SMS1, 0u, a);
    digest_of(VARIANT_G2_MASKED, PROFILE_SMS2, 0u, b);
    CHECK(strcmp(a, b) != 0);
    digest_of(VARIANT_G2, PROFILE_SMS1, 0u, a);
    digest_of(VARIANT_G2, PROFILE_SMS2, 0u, b);
    CHECK(strcmp(a, b) == 0);
    if (csv != NULL)
        check_csv(csv);
    return check_failures;
}

static void *alloc(void *u, size_t n)
{
    (void)u;
    return malloc(n);
}
static void release(void *u, void *p, size_t n)
{
    (void)u;
    (void)n;
    free(p);
}

static int compare(const char *path, enum variant v, enum profile p, uint32_t scenario,
                   uint32_t frames)
{
    static uint8_t image[32768];
    FILE *file = fopen(path, "rb");
    if (file == NULL)
        return 1;
    CHECK_EQ_U64(fread(image, 1u, sizeof image, file), sizeof image);
    CHECK(fclose(file) == 0);
    cogmaster_config cfg = {0};
    cfg.size = sizeof cfg;
    cfg.allocator.alloc = alloc;
    cfg.allocator.free = release;
    cogmaster *m = NULL;
    CHECK_EQ_U64(cogmaster_create(&cfg, &m), COGMASTER_STATUS_OK);
    cogmaster_media media = {0};
    media.size = sizeof media;
    media.image = image;
    media.image_size = sizeof image;
    media.machine = p == PROFILE_SMS1   ? COGMASTER_MACHINE_SMS1
                    : p == PROFILE_SMS2 ? COGMASTER_MACHINE_SMS2
                                        : COGMASTER_MACHINE_GG;
    media.region = COGMASTER_REGION_EXPORT;
    media.tv = COGMASTER_TV_NTSC;
    media.video_mode = COGMASTER_VIDEO_SMS;
    CHECK_EQ_U64(cogmaster_load(m, &media), COGMASTER_STATUS_OK);
    for (uint32_t i = 0u; i < frames; i++)
        CHECK_EQ_U64(cogmaster_run_frame(m, NULL), COGMASTER_STATUS_OK);
    static uint16_t pixels[240][256];
    cogmaster_frame frame = {0};
    frame.size = sizeof frame;
    frame.pixels = &pixels[0][0];
    frame.pitch_bytes = 512u;
    CHECK_EQ_U64(cogmaster_get_frame(m, &frame), COGMASTER_STATUS_OK);
    CHECK_EQ_U64(frame.h, FIELD_H);
    CHECK_EQ_U64(frame.w, FIELD_W);
    int bad = check_failures;
    /* The switch line is a mix of two modes: it is skipped here and only its hash is pinned. */
    for (uint32_t y = 0u; y < FIELD_H && !bad; y++) {
        for (uint32_t x = 0u; x < FIELD_W && !(v == VARIANT_G2_SWITCH && y == SWITCH_LINE); x++) {
            uint16_t want = pixel(v, p, scenario, x, y);
            if (pixels[y][x] != want) {
                fprintf(stderr, "pixel %u,%u: %03x expected %03x\n", x, y, pixels[y][x], want);
                bad = 1;
                break;
            }
        }
    }
    cogmaster_destroy(m);
    return bad || check_failures != 0 ? 1 : 0;
}

static int find(const char *const *names, int count, const char *name)
{
    for (int i = 0; i < count; i++)
        if (strcmp(names[i], name) == 0)
            return i;
    return -1;
}

int main(int argc, char **argv)
{
    if (argc < 5)
        return 2;
    const char *mode = argv[4];
    if (strcmp(mode, "literals") == 0) {
        check_literals(argc > 5 ? argv[5] : NULL);
        CHECK_DONE();
    }
    if (strcmp(mode, "rows") == 0) {
        struct record records[48];
        size_t count = build_records(records);
        for (size_t i = 0u; i < count; i++)
            printf("%02X:%s %s\n", records[i].id, records[i].name, records[i].expected);
        return 0;
    }
    int v = find(variant_names, VARIANT_COUNT, argv[2]);
    int p = find(profile_names, PROFILE_COUNT, argv[3]);
    if (v < 0 || p < 0)
        return 2;
    /* argv[5] is the scenario number (1 to the count) for sprites and the frame count otherwise. */
    uint32_t arg = argc > 5 ? (uint32_t)strtoul(argv[5], NULL, 10) : 0u;
    uint32_t scenario = 0u, frames = arg;
    if (v == VARIANT_SPRITES) {
        if (arg < 1u || arg > SCENARIO_COUNT)
            return 2;
        scenario = arg - 1u;
        frames = SPRITES_FIRST_FRAME + SCENARIO_FRAMES * scenario;
    }
    if (strcmp(mode, "digest") == 0 && v != VARIANT_G2_SWITCH) {
        char hex[65];
        digest_of((enum variant)v, (enum profile)p, scenario, hex);
        puts(hex);
        return 0;
    }
    if (strcmp(mode, "compare") == 0 && frames > 0u)
        return compare(argv[1], (enum variant)v, (enum profile)p, scenario, frames);
    return 2;
}
